#!/usr/bin/env python3
"""Rebuild the Black hole module of index.html from blackhole-lab.html.
Usage: python3 tools/port_blackhole.py blackhole-lab.html index.html
Copies two text ranges of the lab (the 48-band analysis; palettes, uniforms, hole, beams, source points, smoke, stars) into one closure
BHOLE with a step function written for the main app, and puts it just before the frame loop (replacing an earlier copy if there is one).
Not ported: the lab's own transport, glow slider, Stars and Needles buttons (stars are on, needles are 0.675)."""
import sys
lab=open(sys.argv[1]).read(); path=sys.argv[2]; s=open(path).read()
def cut(a,b):
    i=lab.index(a); j=lab.index(b,i); return lab[i:j]
seg1=cut('function fft(re,im)','/* ---------------- rendering')
seg2=cut('const PALS=','const composer=new THREE.EffectComposer')
assert seg2.count('scene.add(')==3; seg2=seg2.replace('scene.add(','root.add(')
mod=r'''/* ================= Black hole: lasers out of a black sphere in space =================
   Generated by tools/port_blackhole.py from blackhole-lab.html (HANDOFF.md, sections 8p to 8w). Change the lab and run the script again;
   do not edit the copied parts here. It listens to the song in 48 bands of its own, worked out the first time the mode is opened for a song. */
const HOLE={on:false};
const BHOLE=((scene,camera,canvas)=>{
const NB=48, NBEAM=2600, R=10;
const root=new THREE.Group(); root.visible=false; scene.add(root);
'''+seg1+seg2+r'''
const orb={az:.6,el:.25,d:62,azT:.6,elT:.25,dT:62,drag:false,x:0,y:0,idle:9};
let on=false;
canvas.addEventListener('pointerdown',e=>{ if(!on) return; orb.drag=true; orb.x=e.clientX; orb.y=e.clientY; });
addEventListener('pointermove',e=>{ if(!on||!orb.drag) return; orb.azT-=(e.clientX-orb.x)*.0025; orb.elT=clamp(orb.elT+(e.clientY-orb.y)*.002,-1.35,1.35); orb.x=e.clientX; orb.y=e.clientY; orb.idle=0; });   /* heavy to drag, slow to settle */
addEventListener('pointerup',()=>orb.drag=false);
canvas.addEventListener('wheel',e=>{ if(!on) return; e.preventDefault(); orb.dT=clamp(orb.dT*Math.exp(e.deltaY*.001),16,220); },{passive:false});
const invM=new THREE.Matrix4(), lev=U.uLev.value, shot=U.uShot.value, smk=U.uSmoke.value, camP=new THREE.Vector3(0,0,62), cA=new THREE.Vector3(), cB=new THREE.Vector3();
let pulse=0, pulseT=0, lastKick=-9, hitI=0, push=0, prevT=0, allT=0, HA=null, curA=null, invK=0;
function step(dt,t,isOn,playing,pxH,getData){
  on=isOn; root.visible=isOn; if(!isOn){ orb.drag=false; return; }
  U.uTime.value+=dt; U.uPx.value=pxH;
  if(curA!==A){ curA=A; HA=null; hitI=0; const mine=A; setTimeout(()=>{ if(curA!==mine) return; const d=getData(); if(d) HA=analyse(d.data,d.sr); },80); }   /* a second or two of listening; the resting hole shows meanwhile */
  const live=playing&&!!HA; let kick=0, bass=0;
  if(HA){ const fr=clamp(t*HA.fps,0,HA.F-1), f0=fr|0, f1=Math.min(HA.F-1,f0+1), k=fr-f0;
    for(let b=0;b<NB;b++){ const L=live?HA.lev[f0*NB+b]*(1-k)+HA.lev[f1*NB+b]*k:0, O=live?Math.max(HA.on[f0*NB+b],HA.on[f1*NB+b]):0;
      lev[b]+=(L-lev[b])*Math.min(1,dt*10); const tgt=Math.max(O,0); shot[b]+=(tgt-shot[b])*Math.min(1,dt*(tgt>shot[b]?26:2.6));
      smk[b]+=(shot[b]-smk[b])*Math.min(1,dt*(shot[b]>smk[b]?2.4:.3)); if(b<6&&live) kick=Math.max(kick,O); if(b<8) bass+=lev[b]/8; }
    if(kick>.62&&t-lastKick>.18){ lastKick=t; pulseT=1; } if(t<lastKick) lastKick=t-1;
    if(Math.abs(t-prevT)>.5) hitI=0; while(hitI<HA.hits.length&&HA.hits[hitI].t<prevT) hitI++;
    if(live) while(hitI<HA.hits.length&&HA.hits[hitI].t<=t){ allT=Math.max(allT,HA.hits[hitI].s); push=Math.max(push,HA.hits[hitI].s); hitI++; } prevT=t; }
  else for(let b=0;b<NB;b++){ lev[b]*=Math.exp(-dt*6); shot[b]*=Math.exp(-dt*3); smk[b]*=Math.exp(-dt*.3); }
  U.uBass.value+=(bass-U.uBass.value)*Math.min(1,dt*8);
  allT*=Math.exp(-dt*2.2); U.uAll.value+=(allT-U.uAll.value)*Math.min(1,dt*14); push*=Math.exp(-dt*1.6);
  U.uA.value.lerp(cA.set(...PALS[palI][1]),Math.min(1,dt*3)); U.uB.value.lerp(cB.set(...PALS[palI][2]),Math.min(1,dt*3));
  orb.idle+=dt; if(!orb.drag&&orb.idle>1.5) orb.azT+=dt*.07;
  orb.az+=(orb.azT-orb.az)*Math.min(1,dt*2.67); orb.el+=(orb.elT-orb.el)*Math.min(1,dt*2.67); orb.d+=(orb.dT*(1-.12*push)-orb.d)*Math.min(1,dt*3);
  const ce=Math.cos(orb.el); camP.set(Math.sin(orb.az)*ce*orb.d,Math.sin(orb.el)*orb.d,Math.cos(orb.az)*ce*orb.d);
  pulse+=(pulseT-pulse)*Math.min(1,dt*(pulseT>pulse?22:6)); pulseT*=Math.exp(-dt*9); { const sc=1+.1*pulse; hole.scale.setScalar(sc); ball.scale.setScalar(sc); }   /* swells on the beat only */
  U.uRand.value+=((PALS[palI][0]==='random'?1:0)-U.uRand.value)*Math.min(1,dt*3); invK+=((PALS[palI][0]==='inverse'?1:0)-invK)*Math.min(1,dt*3);
  stars.rotation.y-=dt*.004; hole.rotation.y-=dt*.05; hole.rotation.x=.25*Math.sin(U.uTime.value*.05); hole.updateMatrixWorld(); U.uCam.value.copy(camP).applyMatrix4(invM.copy(hole.matrixWorld).invert());
  U.uRest.value+=((live?0:1)-U.uRest.value)*Math.min(1,dt*1.5); }
function cam(){ camera.position.copy(camP); camera.up.set(0,1,0); camera.lookAt(0,0,0); }
return {step,cam,inv:()=>invK,next:()=>{ palI=(palI+1)%PALS.length; return PALS[palI][0]; },name:()=>PALS[palI][0]};
})(scene,camera,renderer.domElement);
let hfPass=null;
function holeData(){ if(!buffer) return null; const n=buffer.length, nc=buffer.numberOfChannels, d=new Float32Array(n); for(let c=0;c<nc;c++){ const ch=buffer.getChannelData(c); for(let i=0;i<n;i++) d[i]+=ch[i]/nc; } return {data:d,sr:buffer.sampleRate}; }
function holeStep(dt,t,on){ HOLE.on=on; if(sky.visible===on) sky.visible=!on;   /* its space is its own: plain black and its own stars, without the app's sky and nebula */ BHOLE.step(dt,t,on,playing,renderer.domElement.height,holeData);
  if(composer&&THREE.ShaderPass&&!hfPass){ /* light that piles up keeps its colour; and the inverse palette turns the finished picture over (white space, black lasers) */
    hfPass=new THREE.ShaderPass({uniforms:{tDiffuse:{value:null},uInv:{value:0}},vertexShader:'varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }',
      fragmentShader:'precision highp float; uniform sampler2D tDiffuse; uniform float uInv; varying vec2 vUv; void main(){ vec3 c=texture2D(tDiffuse,vUv).rgb; float m=max(c.r,max(c.g,c.b)); c/=max(1.,m); gl_FragColor=vec4(mix(c,vec3(1.-min(1.,m)),uInv),1.); }'}); hfPass.enabled=false; composer.addPass(hfPass); }
  if(hfPass){ hfPass.enabled=on; hfPass.uniforms.uInv.value=BHOLE.inv(); }
  if(on){ fovOver=58; if(dkPass) dkPass.enabled=false; if(bloom){ bloom.strength=1.35*CT.glow; bloom.radius=1.; bloom.threshold=.05; } } }
function holeCam(){ BHOLE.cam(); U.uCam.value.copy(camera.position); }
/* its colours have their own button in the top bar, shown only in this mode; key L does the same (C is the Controls panel) */
{ const grp=document.createElement('div'); grp.className='seg plate gone'; grp.id='holeSeg'; grp.setAttribute('role','group'); grp.setAttribute('aria-label','Laser colour');
  const b=document.createElement('button'); b.id='btnHoleCol'; b.title='Next laser colour (L)'; const lab=()=>{ const n=BHOLE.name(); b.textContent='Lasers: '+(n==='random'?'multi':n); }; lab();
  const nx=()=>{ BHOLE.next(); lab(); }; b.addEventListener('click',nx); grp.append(b); const sw=document.querySelector('.tools .swwrap'); if(sw) sw.before(grp);   /* it takes the colour button's place in the top bar */
  window.addEventListener('keydown',e=>{ if(world==='hole'&&(e.key==='l'||e.key==='L')&&!e.metaKey&&!e.ctrlKey&&!(e.target&&/INPUT|TEXTAREA/.test(e.target.tagName))) nx(); }); }

'''
M='/* ================= Black hole: lasers out of a black sphere in space'; F='/* ================= frame loop ================= */'
b=s.index(F); a=s.index(M) if M in s else b
s=s[:a]+mod+s[b:]; open(path,'w').write(s); print('ported',len(mod),'chars')
